#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::NewtonPerMinute),
        ForceChangeRate::from_newtons_per_minute(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::NewtonPerMinute),
        ForceChangeRate::from_base(v).as_newtons_per_minute()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::DecanewtonPerMinute),
        ForceChangeRate::from_decanewtons_per_minute(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::DecanewtonPerMinute),
        ForceChangeRate::from_base(v).as_decanewtons_per_minute()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::KilonewtonPerMinute),
        ForceChangeRate::from_kilonewtons_per_minute(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::KilonewtonPerMinute),
        ForceChangeRate::from_base(v).as_kilonewtons_per_minute()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::NewtonPerSecond),
        ForceChangeRate::from_newtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::NewtonPerSecond),
        ForceChangeRate::from_base(v).as_newtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::NanonewtonPerSecond),
        ForceChangeRate::from_nanonewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::NanonewtonPerSecond),
        ForceChangeRate::from_base(v).as_nanonewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::MicronewtonPerSecond),
        ForceChangeRate::from_micronewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::MicronewtonPerSecond),
        ForceChangeRate::from_base(v).as_micronewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::MillinewtonPerSecond),
        ForceChangeRate::from_millinewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::MillinewtonPerSecond),
        ForceChangeRate::from_base(v).as_millinewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::CentinewtonPerSecond),
        ForceChangeRate::from_centinewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::CentinewtonPerSecond),
        ForceChangeRate::from_base(v).as_centinewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::DecinewtonPerSecond),
        ForceChangeRate::from_decinewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::DecinewtonPerSecond),
        ForceChangeRate::from_base(v).as_decinewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::DecanewtonPerSecond),
        ForceChangeRate::from_decanewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::DecanewtonPerSecond),
        ForceChangeRate::from_base(v).as_decanewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::KilonewtonPerSecond),
        ForceChangeRate::from_kilonewtons_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::KilonewtonPerSecond),
        ForceChangeRate::from_base(v).as_kilonewtons_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::PoundForcePerMinute),
        ForceChangeRate::from_pounds_force_per_minute(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::PoundForcePerMinute),
        ForceChangeRate::from_base(v).as_pounds_force_per_minute()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::KilopoundForcePerMinute),
        ForceChangeRate::from_kilopounds_force_per_minute(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::KilopoundForcePerMinute),
        ForceChangeRate::from_base(v).as_kilopounds_force_per_minute()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::PoundForcePerSecond),
        ForceChangeRate::from_pounds_force_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::PoundForcePerSecond),
        ForceChangeRate::from_base(v).as_pounds_force_per_second()
    );
    assert_eq!(
        ForceChangeRate::new(v, ForceChangeRateUnit::KilopoundForcePerSecond),
        ForceChangeRate::from_kilopounds_force_per_second(v)
    );
    assert_eq!(
        ForceChangeRate::from_base(v).convert_to(ForceChangeRateUnit::KilopoundForcePerSecond),
        ForceChangeRate::from_base(v).as_kilopounds_force_per_second()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ForceChangeRate::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ForceChangeRate::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ForceChangeRateUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ForceChangeRate::from_base(0.0).auto_unit().unit,
        ForceChangeRateUnit::NewtonPerSecond
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "N/min".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::NewtonPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "N/min").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::NewtonPerMinute
        ))
    );
    assert_eq!(
        "daN/min".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::DecanewtonPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "daN/min").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::DecanewtonPerMinute
        ))
    );
    assert_eq!(
        "kN/min".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::KilonewtonPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "kN/min").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::KilonewtonPerMinute
        ))
    );
    assert_eq!(
        "N/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::NewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "N/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::NewtonPerSecond
        ))
    );
    assert_eq!(
        "nN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::NanonewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "nN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::NanonewtonPerSecond
        ))
    );
    assert_eq!(
        "µN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::MicronewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "µN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::MicronewtonPerSecond
        ))
    );
    assert_eq!(
        "mN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::MillinewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::MillinewtonPerSecond
        ))
    );
    assert_eq!(
        "cN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::CentinewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "cN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::CentinewtonPerSecond
        ))
    );
    assert_eq!(
        "dN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::DecinewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "dN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::DecinewtonPerSecond
        ))
    );
    assert_eq!(
        "daN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::DecanewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "daN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::DecanewtonPerSecond
        ))
    );
    assert_eq!(
        "kN/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::KilonewtonPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kN/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::KilonewtonPerSecond
        ))
    );
    assert_eq!(
        "lbf/min".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::PoundForcePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "lbf/min").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::PoundForcePerMinute
        ))
    );
    assert_eq!(
        "klbf/min".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::KilopoundForcePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "klbf/min").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::KilopoundForcePerMinute
        ))
    );
    assert_eq!(
        "lbf/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::PoundForcePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lbf/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::PoundForcePerSecond
        ))
    );
    assert_eq!(
        "klbf/s".parse::<ForceChangeRateUnit>(),
        Ok(ForceChangeRateUnit::KilopoundForcePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "klbf/s").parse::<ForceChangeRate>(),
        Ok(ForceChangeRate::new(
            2.5,
            ForceChangeRateUnit::KilopoundForcePerSecond
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ForceChangeRate>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ForceChangeRate::from_base(6.0);
    let b = ForceChangeRate::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ForceChangeRate::<i64>::from_base(7);
    let b = ForceChangeRate::<i64>::from_base(2);
    assert_eq!(a + b, ForceChangeRate::from_base(9));
    assert_eq!(a % b, ForceChangeRate::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ForceChangeRate<i64>>(),
        ForceChangeRate::from_base(9)
    );
}
